(async () => {
      const dormir = (ms) => new Promise((r) => setTimeout(r, ms));
      const resolver = () => {
        const [a, op, b] = [...document.querySelectorAll('.operacion > span')].slice(0, 3).map((x) => x.textContent);
        return op === '+' ? +a + +b : +a - +b;
      };
      const libre = () => document.querySelector('.operacion:not(.operacion--bien):not(.operacion--error)');
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
      const escribir = (v) => {
        const inp = document.querySelector('.entrada-oculta');
        setter.call(inp, v);
        inp.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const errores = [];
      const pausas = [];
      for (let i = 0; i < 4; i++) {
        while (!libre()) await dormir(30);
        await dormir(pausas[i] ?? 250);
        const r = resolver();
        const v = errores.includes(i) ? r + 10 : r;
        if ('escribir' === 'escribir') escribir(String(v));
        else [...document.querySelectorAll('.opcion')].find((b) => +b.lastChild.textContent === v || errores.includes(i))?.click();
        await dormir(120);
      }
      if ('parcial' === 'parcial') {
        while (!libre()) await dormir(30);
        escribir(String(resolver())[0]);
      }
    })()

